# 2. Custom CUDA kernel for matrix multiplication of two square matrices.
#    We implement a naive O(N^3) per-thread dot product (for demonstration).
# ----------------------------------------------------------------------
matmul_upper_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_upper_kernel(const float* A, const float* B, float* C, int N) {
    // Each thread computes one element of the output matrix C[i*N + j]
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N * N) {
        float sum = 0.0f;
        for (int k = 0; k < N; ++k) {
            // A row: A[idx * N + k]
            // B column: B[k * N + idx]   (since we want C[i,j] = sum_k A[i,k] * B[k,j])
            sum += A[idx * N + k] * B[k * N + idx];
        }
        C[idx] = sum;
    }
}

torch::Tensor matrix_mul_cuda(torch::Tensor A, torch::Tensor B) {
    auto N = A.size(0);  # assuming square
    auto out_size = N * N;
    auto d_A = A.data_ptr<float>();
    auto d_B = B.data_ptr<float>();
    auto d_out = torch::zeros_like(A);

    const int block_size = 256;
    const int num_blocks = (out_size + block_size - 1) / block_size;

    // Launch one thread per output element
    matmul_upper_kernel<<<num_blocks, block_size>>>(d_A, d_B, d_out.data_ptr<float()>, N);

    return torch::cudaToTensor(d_out);
}
"""

matmul_custom = load_inline(
